def special(u, k, a):
    if a[u] == 1:
        return k - u
    if a[k] == 1000:
        return k - u
    return k - u - 1

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))
    a.sort()
    max_val = 0
    g = True
    u = 0
    for i in range(n - 1):
        if a[i+1] - a[i] == 1 and g:
            u = i
            g = False
        if a[i+1] - a[i] != 1 and not g:
            k = i
            g = True
            l = special(u, k, a)
            if l > max_val:
                max_val = l
    if not g:
        k = n - 1
        l = special(u, k, a)
        if l > max_val:
            max_val = l
    print(max_val)

if __name__ == "__main__":
    main()

